CREATE TABLE documents(id TEXT PRIMARY KEY, plant_id TEXT NOT NULL REFERENCES plants(id), title TEXT NOT NULL, revision TEXT NOT NULL, equipment_types TEXT NOT NULL, asset_ids TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('pending','approved','quarantined','revoked')), content_path TEXT NOT NULL, sha256 TEXT NOT NULL, created_by TEXT NOT NULL REFERENCES users(id), created_at TEXT NOT NULL, approved_by TEXT REFERENCES users(id), approved_at TEXT, metadata TEXT NOT NULL, UNIQUE(plant_id,title,revision));
CREATE TABLE document_grants(user_id TEXT NOT NULL REFERENCES users(id), document_id TEXT NOT NULL REFERENCES documents(id), PRIMARY KEY(user_id,document_id));
CREATE TABLE document_chunks(id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES documents(id), page INTEGER NOT NULL, section TEXT NOT NULL, content TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN('reference','hypothesis','alternative','check','safety')), embedding BLOB, embedding_version TEXT, reviewed INTEGER NOT NULL DEFAULT 0 CHECK(reviewed IN(0,1)));
CREATE INDEX chunks_document ON document_chunks(document_id);
CREATE TABLE maintenance_records(id TEXT PRIMARY KEY, asset_id TEXT NOT NULL REFERENCES assets(id), source_id TEXT NOT NULL REFERENCES sources(id), external_id TEXT NOT NULL, record_type TEXT NOT NULL CHECK(record_type IN('fault','inspection','work_order','schedule')), timestamp_utc TEXT NOT NULL, summary TEXT NOT NULL, details TEXT NOT NULL, imported_at TEXT NOT NULL, UNIQUE(source_id,external_id));
CREATE TABLE copilot_sessions(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), asset_id TEXT NOT NULL REFERENCES assets(id), created_at TEXT NOT NULL);
CREATE TABLE copilot_messages(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES copilot_sessions(id), role TEXT NOT NULL CHECK(role IN('user','assistant')), content TEXT NOT NULL, timestamp_utc TEXT NOT NULL, trace_id TEXT);
CREATE TABLE copilot_traces(id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES copilot_sessions(id), user_id TEXT NOT NULL REFERENCES users(id), asset_id TEXT NOT NULL REFERENCES assets(id), timestamp_utc TEXT NOT NULL, config_version TEXT NOT NULL, status TEXT NOT NULL, details TEXT NOT NULL);
CREATE TABLE investigations(id TEXT PRIMARY KEY, asset_id TEXT NOT NULL REFERENCES assets(id), author_id TEXT NOT NULL REFERENCES users(id), session_id TEXT REFERENCES copilot_sessions(id), notes TEXT NOT NULL, report TEXT NOT NULL, evidence_ids TEXT NOT NULL, created_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('draft','reviewed')));
CREATE TABLE copilot_feedback(id TEXT PRIMARY KEY, message_id TEXT NOT NULL REFERENCES copilot_messages(id), user_id TEXT NOT NULL REFERENCES users(id), rating INTEGER NOT NULL CHECK(rating IN(-1,1)), comment TEXT NOT NULL, created_at TEXT NOT NULL);
